package com.tapbolt.app;
import android.app.Activity;import android.os.Bundle;import android.webkit.WebSettings;import android.webkit.WebView;import android.webkit.WebViewClient;import android.view.View;
public class MainActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);WebView w=new WebView(this);w.setWebViewClient(new WebViewClient());WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);w.setOverScrollMode(View.OVER_SCROLL_NEVER);w.loadUrl("https://akhileshsavali18-beep.github.io/TapBolt/web/");setContentView(w);}}